/**
 * One component of a view, told apart by type. A type an app does not know is skipped and the rest drawn.
 */
@Serializable(with = ExtensionComponentSerializer::class)
sealed interface ExtensionComponent {
    val type: String

    /** A type this app does not know, or a variant it could not read: skipped when drawn. */
    data class Unknown(override val type: String, val raw: JsonObject = JsonObject(emptyMap())) : ExtensionComponent

    companion object {
        val TYPES = listOf("text", "metric", "progress", "row", "button", "link", "field", "divider", "chart", "stat_grid", "segmented", "markdown", "table", "empty", "loading", "html", "header", "breadcrumb", "file_tree", "code", "diff", "comment_thread", "composer", "image", "grid", "carousel")
        val SINCE = mapOf("text" to 1, "metric" to 1, "progress" to 1, "row" to 1, "button" to 1, "link" to 1, "field" to 1, "divider" to 1, "chart" to 2, "stat_grid" to 2, "segmented" to 2, "markdown" to 3, "table" to 3, "empty" to 3, "loading" to 3, "html" to 4, "header" to 4, "breadcrumb" to 4, "file_tree" to 4, "code" to 4, "diff" to 4, "comment_thread" to 4, "composer" to 4, "image" to 6, "grid" to 6, "carousel" to 6)
    }
}

object ExtensionComponentSerializer : KSerializer<ExtensionComponent> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun deserialize(decoder: Decoder): ExtensionComponent {
        val input = decoder as? JsonDecoder ?: throw SerializationException("ExtensionComponent needs JSON")
        val obj = input.decodeJsonElement() as? JsonObject
            ?: return ExtensionComponent.Unknown("")
        val tag = (obj["type"] as? JsonPrimitive)?.contentOrNull ?: ""
        return try {
            when (tag) {
                "text" -> input.json.decodeFromJsonElement(ExtensionTextComponent.serializer(), obj)
                "metric" -> input.json.decodeFromJsonElement(ExtensionMetricComponent.serializer(), obj)
                "progress" -> input.json.decodeFromJsonElement(ExtensionProgressComponent.serializer(), obj)
                "row" -> input.json.decodeFromJsonElement(ExtensionRowComponent.serializer(), obj)
                "button" -> input.json.decodeFromJsonElement(ExtensionButtonComponent.serializer(), obj)
                "link" -> input.json.decodeFromJsonElement(ExtensionLinkComponent.serializer(), obj)
                "field" -> input.json.decodeFromJsonElement(ExtensionFieldComponent.serializer(), obj)
                "divider" -> input.json.decodeFromJsonElement(ExtensionDividerComponent.serializer(), obj)
                "chart" -> input.json.decodeFromJsonElement(ExtensionChartComponent.serializer(), obj)
                "stat_grid" -> input.json.decodeFromJsonElement(ExtensionStatGridComponent.serializer(), obj)
                "segmented" -> input.json.decodeFromJsonElement(ExtensionSegmentedComponent.serializer(), obj)
                "markdown" -> input.json.decodeFromJsonElement(ExtensionMarkdownComponent.serializer(), obj)
                "table" -> input.json.decodeFromJsonElement(ExtensionTableComponent.serializer(), obj)
                "empty" -> input.json.decodeFromJsonElement(ExtensionEmptyComponent.serializer(), obj)
                "loading" -> input.json.decodeFromJsonElement(ExtensionLoadingComponent.serializer(), obj)
                "html" -> input.json.decodeFromJsonElement(ExtensionHtmlComponent.serializer(), obj)
                "header" -> input.json.decodeFromJsonElement(ExtensionHeaderComponent.serializer(), obj)
                "breadcrumb" -> input.json.decodeFromJsonElement(ExtensionBreadcrumbComponent.serializer(), obj)
                "file_tree" -> input.json.decodeFromJsonElement(ExtensionFileTreeComponent.serializer(), obj)
                "code" -> input.json.decodeFromJsonElement(ExtensionCodeComponent.serializer(), obj)
                "diff" -> input.json.decodeFromJsonElement(ExtensionDiffComponent.serializer(), obj)
                "comment_thread" -> input.json.decodeFromJsonElement(ExtensionCommentThreadComponent.serializer(), obj)
                "composer" -> input.json.decodeFromJsonElement(ExtensionComposerComponent.serializer(), obj)
                "image" -> input.json.decodeFromJsonElement(ExtensionImageComponent.serializer(), obj)
                "grid" -> input.json.decodeFromJsonElement(ExtensionGridComponent.serializer(), obj)
                "carousel" -> input.json.decodeFromJsonElement(ExtensionCarouselComponent.serializer(), obj)
                else -> ExtensionComponent.Unknown(tag, obj)
            }
        } catch (_: SerializationException) {
            ExtensionComponent.Unknown(tag, obj)
        } catch (_: IllegalArgumentException) {
            ExtensionComponent.Unknown(tag, obj)
        }
    }

    override fun serialize(encoder: Encoder, value: ExtensionComponent) {
        val output = encoder as? JsonEncoder ?: throw SerializationException("ExtensionComponent needs JSON")
        val obj = when (value) {
            is ExtensionTextComponent -> output.json.encodeToJsonElement(ExtensionTextComponent.serializer(), value) as JsonObject
            is ExtensionMetricComponent -> output.json.encodeToJsonElement(ExtensionMetricComponent.serializer(), value) as JsonObject
            is ExtensionProgressComponent -> output.json.encodeToJsonElement(ExtensionProgressComponent.serializer(), value) as JsonObject
            is ExtensionRowComponent -> output.json.encodeToJsonElement(ExtensionRowComponent.serializer(), value) as JsonObject
            is ExtensionButtonComponent -> output.json.encodeToJsonElement(ExtensionButtonComponent.serializer(), value) as JsonObject
            is ExtensionLinkComponent -> output.json.encodeToJsonElement(ExtensionLinkComponent.serializer(), value) as JsonObject
            is ExtensionFieldComponent -> output.json.encodeToJsonElement(ExtensionFieldComponent.serializer(), value) as JsonObject
            is ExtensionDividerComponent -> output.json.encodeToJsonElement(ExtensionDividerComponent.serializer(), value) as JsonObject
            is ExtensionChartComponent -> output.json.encodeToJsonElement(ExtensionChartComponent.serializer(), value) as JsonObject
            is ExtensionStatGridComponent -> output.json.encodeToJsonElement(ExtensionStatGridComponent.serializer(), value) as JsonObject
            is ExtensionSegmentedComponent -> output.json.encodeToJsonElement(ExtensionSegmentedComponent.serializer(), value) as JsonObject
            is ExtensionMarkdownComponent -> output.json.encodeToJsonElement(ExtensionMarkdownComponent.serializer(), value) as JsonObject
            is ExtensionTableComponent -> output.json.encodeToJsonElement(ExtensionTableComponent.serializer(), value) as JsonObject
            is ExtensionEmptyComponent -> output.json.encodeToJsonElement(ExtensionEmptyComponent.serializer(), value) as JsonObject
            is ExtensionLoadingComponent -> output.json.encodeToJsonElement(ExtensionLoadingComponent.serializer(), value) as JsonObject
            is ExtensionHtmlComponent -> output.json.encodeToJsonElement(ExtensionHtmlComponent.serializer(), value) as JsonObject
            is ExtensionHeaderComponent -> output.json.encodeToJsonElement(ExtensionHeaderComponent.serializer(), value) as JsonObject
            is ExtensionBreadcrumbComponent -> output.json.encodeToJsonElement(ExtensionBreadcrumbComponent.serializer(), value) as JsonObject
            is ExtensionFileTreeComponent -> output.json.encodeToJsonElement(ExtensionFileTreeComponent.serializer(), value) as JsonObject
            is ExtensionCodeComponent -> output.json.encodeToJsonElement(ExtensionCodeComponent.serializer(), value) as JsonObject
            is ExtensionDiffComponent -> output.json.encodeToJsonElement(ExtensionDiffComponent.serializer(), value) as JsonObject
            is ExtensionCommentThreadComponent -> output.json.encodeToJsonElement(ExtensionCommentThreadComponent.serializer(), value) as JsonObject
            is ExtensionComposerComponent -> output.json.encodeToJsonElement(ExtensionComposerComponent.serializer(), value) as JsonObject
            is ExtensionImageComponent -> output.json.encodeToJsonElement(ExtensionImageComponent.serializer(), value) as JsonObject
            is ExtensionGridComponent -> output.json.encodeToJsonElement(ExtensionGridComponent.serializer(), value) as JsonObject
            is ExtensionCarouselComponent -> output.json.encodeToJsonElement(ExtensionCarouselComponent.serializer(), value) as JsonObject
            is ExtensionComponent.Unknown -> value.raw
        }
        output.encodeJsonElement(JsonObject(obj + ("type" to JsonPrimitive(value.type))))
    }
}

